"""
        Parameters
        ----------
        categories_list : list of str
           the list of category's names
        Returns
        -------
            the categories' dictionary
    """
def _write_categories(categories_list: Any) -> object {
    categories_dict = {"categories": []};
    for (id, category) in enumerate(categories_list) {
        category_dict = {"id": (id + 1), "name": category, "supercategory": category};
        categories_dict["categories"].append(category_dict);
    }
    return categories_dict;
}

test_blocks:
test "t0" {
    assert (
        _write_categories(["building", "ground", "road", "sky", "vegetation", "water"])
        == {
            "categories": [
                {"id": 1, "name": "building", "supercategory": "building"},
                {"id": 2, "name": "ground", "supercategory": "ground"},
                {"id": 3, "name": "road", "supercategory": "road"},
                {"id": 4, "name": "sky", "supercategory": "sky"},
                {"id": 5, "name": "vegetation", "supercategory": "vegetation"},
                {"id": 6, "name": "water", "supercategory": "water"}
            ]
        }
    );;
}

test "t1" {
    assert (
        _write_categories(["animal"])
        == {"categories": [{"id": 1, "name": "animal", "supercategory": "animal"}]}
    );;
}

test "t2" {
    assert (
        _write_categories(["animal", "building", "furniture"])
        == {
            "categories": [
                {"id": 1, "name": "animal", "supercategory": "animal"},
                {"id": 2, "name": "building", "supercategory": "building"},
                {"id": 3, "name": "furniture", "supercategory": "furniture"}
            ]
        }
    );;
}

test "t3" {
    assert (_write_categories([]) == {"categories": []});;
}

test "t4" {
    assert (
        _write_categories(["a", "b", "c"])
        == {
            "categories": [
                {"id": 1, "name": "a", "supercategory": "a"},
                {"id": 2, "name": "b", "supercategory": "b"},
                {"id": 3, "name": "c", "supercategory": "c"}
            ]
        }
    );;
}
